  "claim": {
    "component_id": "C006.component",
    "value": "Equipment unreadiness must be distinguished from delayed crew collection.",
    "scope": "Interpretation of late booking starts.",
    "provenance": {
      "refs": [
        {
          "source_id": "P004",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The mapping explicitly requires this distinction without attributing a particular late start to either explanation."
    }
  },
  "signal_basis": {
    "component_id": "C006.signal_basis",
    "value": "Tests record return, cleaning completion, readiness communication, collection and start times, alongside whether lateness reproduces; the informative pattern is repeated lateness under reduction with specified further removals ending reproduction.",
    "scope": "Interpretation of the selected turnaround replay and its tested reductions.",
    "provenance": {
      "refs": [
        {
          "source_id": "P017",
          "role": "SUPPORT"
        },
